const startDraft=(e:Experience):Draft=>({role:e.role,action:e.action,result:e.result,learn:e.reflections.at(-1)?.facts.learn||'',step:0,body:'',ready:false,dirty:false});
const activate=(e:ReactKeyboardEvent,fn:()=>void)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn();}};
function Icon({name,size=20}:{name:string;size?:number}){const p:Record<string,string>={leaf:'M12 21C5 17 2 10 4 4c5 .5 7 3 8 7 1-4 4-6 8-7 2 6-1 13-8 17z M12 11v10',graph:'M6 6l12 2-7 11L6 6z M6 6h.1 M18 8h.1 M11 19h.1',archive:'M4 5h16v4H4z M6 9v11h12V9 M10 13h4',search:'M10 4a6 6 0 1 0 0 12 6 6 0 0 0 0-12z M15 15l5 5',settings:'M5 6h14 M5 12h14 M5 18h14 M9 3v6 M15 9v6 M9 15v6',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',back:'M19 12H5 M11 6l-6 6 6 6',check:'M4 12l5 5L20 6',close:'M6 6l12 12 M18 6 6 18',bookmark:'M6 4h12v17l-6-4-6 4V4z',edit:'M4 20h4L19 9l-4-4L4 16v4z',chat:'M4 5h16v11H9l-5 4V5z M8 9h8',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z'};return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={p[name]||p.arrow}/></svg>}
function Thumb({tone=0}:{tone?:number}){return <svg className={'thumb tone-'+tone%4} viewBox="0 0 320 145" aria-hidden="true"><rect width="320" height="145" rx="15" fill="currentColor"/><circle cx={95+tone%3*15} cy="73" r="39" fill="#8dc63f"/><rect x="155" y="36" width="88" height="76" rx={tone%2?36:12} fill="#eff5e4"/><path d="M64 119c42-57 93-63 168-30" stroke="#124633" strokeWidth="5" fill="none"/></svg>}

export default function App(){
 const [route,setRoute]=useState<Route>('growth');const [experiences,setExperiences]=useState<Experience[]>(seed);const [links,setLinks]=useState<Link[]>(initialLinks);const [focus,setFocus]=useState<Focus|null>(null);const [focusTick,setFocusTick]=useState(0);const [expanded,setExpanded]=useState(false);const [lens,setLens]=useState(true);const [selectedLink,setSelectedLink]=useState<string|null>(null);
 const [archiveId,setArchiveId]=useState<string|null>(null);const [archiveTab,setArchiveTab]=useState('경험 기록');const [archiveSettings,setArchiveSettings]=useState({search:'',type:'전체',status:'전체',view:'갤러리'});const [drafts,setDrafts]=useState<Record<string,Draft>>({});const [bookmarks,setBookmarks]=useState<string[]>([]);const [exploreSettings,setExploreSettings]=useState({source:'전체',axis:'전체',saved:false});
 const [exploreMode,setExploreMode]=useState('activities');const [careerField,setCareerField]=useState('all');const [jobBookmarks,setJobBookmarks]=useState<string[]>([]);const [careerOverrides,setCareerOverrides]=useState<CareerOverrides>({});
 const [activity,setActivity]=useState<Activity|null>(null);const [editor,setEditor]=useState<Experience|null>(null);const [deleteId,setDeleteId]=useState<string|null>(null);const [linkEditor,setLinkEditor]=useState<Link|null>(null);const [resetOpen,setResetOpen]=useState(false);const [info,setInfo]=useState(false);const [patternEdit,setPatternEdit]=useState<string|null>(null);const [overrides,setOverrides]=useState<Record<string,{label:string;note:string;status:string}>>({});const [toast,setToast]=useState('');const [revision,setRevision]=useState(0);const [doneRevision,setDoneRevision]=useState(0);const [analysis,setAnalysis]=useState('완료');const [queueLabel,setQueueLabel]=useState('새 변경 없음');const [recheckIds,setRecheckIds]=useState<string[]>([]);
 const ids=new Set(experiences.map(e=>e.id));const aliveLinks=links.filter(l=>ids.has(l.from)&&ids.has(l.to));const selectedIds=focus?.ids.filter(id=>ids.has(id))||[];const stale=revision>doneRevision;const current=experiences.find(e=>e.id===archiveId);const activePattern=patterns.find(p=>focus?.type==='pattern'&&p.id===focus.key);const inspectedLink=aliveLinks.find(l=>l.id===selectedLink);
 const focusedReflection=focus?.type==='node'?experiences.flatMap(e=>e.reflections.map(r=>({experience:e,reflection:r}))).find(v=>v.reflection.id===focus?.key):undefined;
 const counts=axes.map(a=>({axis:a,count:experiences.filter(e=>e.axes.includes(a.id)).length}));
 const change=(label:string)=>{setRevision(v=>v+1);setAnalysis('대기');setQueueLabel(label);};
 const navigate=(r:Route)=>{setRoute(r);setActivity(null);window.scrollTo({top:0,behavior:'smooth'});};
 const highlight=(f:Focus,scroll=false)=>{setFocus(f);setFocusTick(t=>t+1);setSelectedLink(null);setRoute('growth');setActivity(null);if(scroll)setTimeout(()=>document.getElementById('growth-graph')?.scrollIntoView({block:'center',behavior:'smooth'}),40);};
 const openArchive=(id:string,tab='경험 기록')=>{setArchiveId(id);setArchiveTab(tab);navigate('archive');};
 const toggleBookmark=(id:string)=>setBookmarks(old=>old.includes(id)?old.filter(x=>x!==id):[...old,id]);
 const invalidatePatternConfirmation=(id:string)=>setOverrides(old=>{const next={...old};patterns.filter(p=>p.ids.includes(id)).forEach(p=>delete next[p.id]);return next;});
 const invalidateCareerMatches=(id:string,removed=false)=>setCareerOverrides(old=>Object.fromEntries(Object.entries(old).map(([key,value])=>[key,value.ids.includes(id)?{...value,ids:removed?value.ids.filter(x=>x!==id):value.ids,status:'proposed' as const,invalidated:removed?'deleted' as const:'edited' as const,invalidatedExperienceId:id}:value])));
 const saveExperience=(e:Experience)=>{const saved={...e,title:e.title.trim(),id:e.id||'e-'+Date.now().toString(36)};setExperiences(old=>e.id?old.map(x=>x.id===e.id?saved:x):[...old,saved]);if(e.id){setRecheckIds(old=>[...new Set([...old,e.id])]);invalidatePatternConfirmation(e.id);invalidateCareerMatches(e.id);setLinks(old=>old.map(l=>l.from===e.id||l.to===e.id?{...l,status:'proposed',reason:l.reason.startsWith('기록 정정 후')?l.reason:'기록 정정 후 재확인이 필요합니다. 이전 연결 근거: '+l.reason}:l));}setFocus(null);setSelectedLink(null);setPatternEdit(null);setEditor(null);setArchiveId(saved.id);setArchiveTab('경험 기록');setRoute('archive');change(saved.title+' 기록 변경');setToast('경험 기록이 저장됐어요. 수정된 기록의 해석과 연결은 재확인 전까지 미확인입니다.');};
 const deleteExperience=()=>{if(!deleteId)return;setExperiences(old=>old.filter(e=>e.id!==deleteId));setLinks(old=>old.filter(l=>l.from!==deleteId&&l.to!==deleteId));setDrafts(old=>{const next={...old};delete next[deleteId];return next;});setRecheckIds(old=>old.filter(id=>id!==deleteId));invalidatePatternConfirmation(deleteId);invalidateCareerMatches(deleteId,true);setArchiveId(old=>old===deleteId?null:old);setFocus(null);setSelectedLink(null);setPatternEdit(null);setDeleteId(null);change('경험 삭제 · 파생 근거 재검토 대기');setToast('경험·회고·연결 근거를 데모 메모리에서 함께 삭제하고 관련 해석의 확인 상태를 해제했어요.');};
 const updateDraft=(id:string,patch:Partial<Draft>)=>setDrafts(old=>({...old,[id]:{...(old[id]||startDraft(experiences.find(e=>e.id===id)!)),...patch,dirty:true}}));
 const saveReflection=(e:Experience,d:Draft)=>{const record:ReflectionRecord={id:'r-'+Date.now().toString(36),version:e.reflections.length+1,body:d.body.trim(),facts:{role:d.role,action:d.action,result:d.result,learn:d.learn},at:new Date().toLocaleString('ko-KR')};setExperiences(old=>old.map(x=>x.id===e.id?{...x,reflections:[...x.reflections,record]}:x));setDrafts(old=>{const n={...old};delete n[e.id];return n;});setArchiveTab('회고');change(e.title+' 회고 저장');setToast('회고 v'+record.version+'이 이 경험의 아카이브에 저장됐어요. 원문 근거는 그대로 보존했습니다.');};
 const reset=()=>{setExperiences(seed);setLinks(initialLinks);setFocus(null);setSelectedLink(null);setDrafts({});setBookMarksEmpty();setArchiveId(null);setArchiveTab('경험 기록');setArchiveSettings({search:'',type:'전체',status:'전체',view:'갤러리'});setExploreSettings({source:'전체',axis:'전체',saved:false});setOverrides({});setCareerOverrides({});setJobBookmarks([]);setCareerField('all');setExploreMode('activities');setRecheckIds([]);setRevision(0);setDoneRevision(0);setAnalysis('완료');setQueueLabel('새 변경 없음');setExpanded(false);setResetOpen(false);setRoute('growth');setToast('예시 상태로 초기화했어요.');};
 const setBookMarksEmpty=()=>setBookmarks([]);
 const focusPattern=(p:typeof patterns[number])=>{const related=p.ids.filter(id=>ids.has(id)&&!recheckIds.includes(id));highlight({type:'pattern',key:p.id,label:related.length<2?'강점 가설 · 연결 근거 보완 필요':overrides[p.id]?.label||p.title,ids:related},true);};
 const focusAxis=(axis:Axis)=>highlight({type:'axis',key:axis,label:axisLabel(axis)+' 경험 근거',ids:experiences.filter(e=>e.axes.includes(axis)).map(e=>e.id)},true);
 const focusNode=(node:Node)=>{const neighbor=aliveLinks.filter(l=>l.from===node.eid||l.to===node.eid).flatMap(l=>[l.from,l.to]);highlight({type:'node',key:node.id,label:node.label+'의 연결',ids:node.kind==='experience'?[...new Set([node.eid,...neighbor])]:[node.eid]});};
 const focusLink=(l:Link)=>{highlight({type:'link',key:l.id,label:l.label,ids:[l.from,l.to]});setSelectedLink(l.id);};
 const activityFocus=(a:Activity)=>highlight({type:'activity',key:a.id,label:a.title+'과 연결된 경험',ids:a.ids.filter(id=>ids.has(id))},true);
 const patternValues=patterns.map(p=>({...p,records:experiences.filter(e=>p.ids.includes(e.id)&&!recheckIds.includes(e.id)),note:overrides[p.id]?.note||p.note,label:overrides[p.id]?.label||p.title,status:overrides[p.id]?.status||'예시 분석 · 가설'}));
 const filteredActivities=opportunities.filter(a=>(exploreSettings.source==='전체'||a.source===exploreSettings.source)&&(exploreSettings.axis==='전체'||a.axis===exploreSettings.axis)&&(!exploreSettings.saved||bookmarks.includes(a.id)));
 const careerHighlight=(relatedIds:string[],label:string)=>highlight({type:'job',key:'career-'+label,label,ids:relatedIds},true);
 const browseCareer=(id:string)=>{setCareerField(id);setExploreMode('jobs');navigate('explore');};
 const navItems:{id:Route;label:string;icon:string}[]=[{id:'growth',label:'내 성장',icon:'graph'},{id:'archive',label:'경험 아카이브',icon:'archive'},{id:'explore',label:'활동 탐색',icon:'search'}];
 return <div className="app"><aside className="sidebar"><div className="brand"><Icon name="leaf" size={34}/><span><small>SKKU · COMPANION</small><strong>킹고 컴패니언</strong></span></div><nav aria-label="주요 화면">{navItems.map(n=><button key={n.id} className={route===n.id?'active':''} aria-current={route===n.id?'page':undefined} onClick={()=>navigate(n.id)}><Icon name={n.icon}/>{n.label}</button>)}</nav><div className="side-note"><span className="dot"/>경험 → 회고 → 발견 → 다음 경험</div><div className="side-bottom"><button className={route==='data'?'active':''} onClick={()=>navigate('data')}><Icon name="settings"/>데이터·설정</button><small>경험·채용 연결 UX v0.6</small></div></aside><div className="workspace"><header className="topbar"><div><span className="demo-pill">경험 예시 · 채용 원문 표본</span><span className="top-hint">실제 AI 미연결 · 메모리 데모</span></div><button className="text-button" onClick={()=>setInfo(true)}>데모 안내</button></header><main>
 {toast&&<div className="notice" role="status"><Icon name="check"/><span>{toast}</span><button aria-label="알림 닫기" onClick={()=>setToast('')}><Icon name="close" size={16}/></button></div>}
 {route==='growth'&&<><PageTitle eyebrow="MY GROWTH" title="내 경험은 어떻게 이어질까요?" subtitle="분석 문장을 눌러, 그 해석을 뒷받침하는 활동과 연결을 확인해요." action={<button className="primary" onClick={()=>{setEditor(blankExperience());}}>경험 남기기<Icon name="plus"/></button>}/><div className="analysis-strip"><span className={stale?'state waiting':'state'}>{stale?'새 변경 분석 대기':'저장된 예시 분석'}</span><small>{stale?'수정·삭제된 원문은 기존 가설의 근거에서 제외합니다. 새 회고 분석은 별도 대기합니다.':'가설을 고를 때마다 모델을 새로 호출하지 않습니다.'}</small><button className="text-button" onClick={()=>navigate('data')}>상태 확인</button></div><section className="pattern-grid" aria-label="경험 기반 분석">{patternValues.map(p=><button key={p.id} className={'pattern-card '+(focus?.key===p.id?'selected':'')} aria-pressed={focus?.key===p.id} onClick={()=>focusPattern(p)}><span className="pattern-top"><Icon name="spark"/><small>{p.records.length<2?'근거 보완 필요':p.status}</small></span><strong>{p.records.length<2?'연결 근거를 더 모아볼까요?':p.label}</strong><span>{p.records.length<2?'현재 관련 경험이 '+p.records.length+'개입니다. 반복되는 강점으로 해석하지 않습니다.':p.note}</span><b>{p.records.length}개 경험의 연결 보기 <Icon name="arrow" size={15}/></b></button>)}</section><div className="growth-grid"><section className="graph-card" id="growth-graph"><div className="panel-head"><div><h2>경험 연결 지도</h2><small>{experiences.length}개 활동 · 활동 사이의 재사용과 다음 시도</small></div><button className={expanded?'selected':''} aria-pressed={expanded} onClick={()=>setExpanded(v=>!v)}>{expanded?'활동 중심으로':'근거 펼치기'}</button></div><div className="graph-legend"><span><i/>확인된 연결</span><span><i className="dashed"/>연결 제안</span><span className="artifact-mark"/>결과물<span className="reflection-mark"/>회고</div><div className="focus-bar" role="status" aria-live="polite">{focus?<><span><strong>{selectedIds.length}개 관련 경험 강조</strong><small>{focus.label}</small></span><button onClick={()=>{setFocus(null);setSelectedLink(null);}}>강조 해제</button></>:<span>분석·노드·6축을 선택하면 같은 경험 근거가 강조돼요.</span>}</div><ExperienceGraph experiences={experiences} links={aliveLinks} focusIds={focus?selectedIds:null} tick={focusTick} expanded={expanded} selectNode={focusNode} selectLink={focusLink}/>{experiences.length===0&&<Empty title="아직 연결할 경험이 없어요" text="기록이 없다는 것은 낮은 능력이 아닌 미확인입니다." label="첫 경험 남기기" action={()=>setEditor(blankExperience())}/>}</section><aside className="evidence-inspector" aria-label="선택한 분석의 근거"><div className="inspector-head"><small>WHY THIS CONNECTION</small><h2>{focus?focus.label:'연결의 이유를 읽어봐요'}</h2></div>{inspectedLink&&<div className="relation-reason"><span className="state">{inspectedLink.status==='confirmed'?'학생 확인 · 예시':'확인 전 제안'}</span><p>{inspectedLink.reason}</p><button onClick={()=>setLinkEditor(inspectedLink)}>연결 확인·수정</button></div>}{!focus&&<p className="muted">위 분석 문장이나 지도 속 활동을 선택하세요. 원문·직접 한 행동·관련 경험을 이곳에서 확인할 수 있어요.</p>}{focus&&selectedIds.length===0&&<p className="muted">현재 남아 있는 근거가 없습니다. 미확인 상태이며 낮은 능력을 뜻하지 않습니다.</p>}{focusedReflection&&<section className="reflection-interpretation"><span className="pill">학생이 저장한 회고 · 원문과 분리</span><h3>{focusedReflection.experience.title} · 회고 v{focusedReflection.reflection.version}</h3><p className="saved-body">{focusedReflection.reflection.body}</p><small>{focusedReflection.reflection.at} · 아래 원문과 직접 한 행동은 별도로 보존됩니다.</small></section>}{selectedIds.map(id=>{const e=experiences.find(x=>x.id===id)!;return <article className="evidence-item" key={id}><small>{e.type} · {e.period}</small><h3>{e.title}</h3><blockquote>“{e.quote||'원문 근거 미확인'}”</blockquote><p><b>내 행동</b> {e.action||'미확인'}</p><button onClick={()=>openArchive(e.id)}>아카이브에서 근거 보기<Icon name="arrow" size={14}/></button></article>})}{activePattern&&selectedIds.length>=2&&<div className="assumption-actions"><small>가설은 내가 확인해요</small><button onClick={()=>{setOverrides(o=>({...o,[activePattern.id]:{label:o[activePattern.id]?.label||activePattern.title,note:o[activePattern.id]?.note||'',status:'학생이 확인한 예시 해석'}}));change('분석 해석 사용자 확인');}}>이 해석에 동의</button><button onClick={()=>setPatternEdit(activePattern.id)}>다른 해석으로 수정</button></div>}</aside></div><div className="section-head"><div><h2>6축 경험 렌즈</h2><p>특성표를 점수가 아닌, 근거로 연결되는 지도로 다시 사용해요.</p></div><button aria-expanded={lens} onClick={()=>setLens(v=>!v)}>{lens?'6축 접기':'6축 펼치기'}</button></div>{lens&&<section className="lens-panel"><HexLens counts={counts} total={experiences.length} active={focus?.type==='axis'?focus.key:''} select={focusAxis}/><div className="lens-copy"><span className="pill">능력 점수 아님</span><h3>축을 누르면 관련 경험이 켜져요</h3><p>반경 = 해당 축에 직접 연결된 경험 수 ÷ 전체 경험 수. 기록의 연결 분포이며 실력·순위·성격·직업 적합성을 평가하지 않습니다.</p><div className="axis-list">{counts.map(({axis,count})=><button key={axis.id} className={focus?.key===axis.id?'selected':''} aria-pressed={focus?.key===axis.id} onClick={()=>focusAxis(axis.id)}><span>{axis.label}<small>{axis.hint}</small></span><b>{count?'근거 '+count+'개':'미확인'}</b></button>)}</div><small>0개는 낮은 능력이 아니라 아직 연결된 기록이 없음. 축 연결은 경험 편집에서 직접 수정할 수 있어요.</small></div></section>}<CareerOverview experiences={experiences} recheckIds={recheckIds} overrides={careerOverrides} onBrowseField={browseCareer} onHighlight={careerHighlight}/><div className="section-head"><h2>이 발견에서 다음 경험으로</h2><button className="text-button" onClick={()=>navigate('explore')}>활동 탐색 전체 보기<Icon name="arrow"/></button></div><div className="activity-grid">{opportunities.slice(0,3).map((a,i)=><ActivityCard key={a.id} activity={a} saved={bookmarks.includes(a.id)} toggle={()=>toggleBookmark(a.id)} open={()=>setActivity(a)} tone={i}/>)}</div></>}
 {route==='archive'&&<><PageTitle eyebrow="EXPERIENCE ARCHIVE" title="경험과 회고를 한곳에" subtitle="경험의 원문, 내가 남긴 회고, 연결된 근거가 같은 기록 안에 쌓여요." action={<button className="primary" onClick={()=>setEditor(blankExperience())}><Icon name="plus"/>경험 추가</button>}/>{!current?<><ArchiveFilters settings={archiveSettings} update={p=>setArchiveSettings(s=>({...s,...p}))}/><div className={'archive-grid '+(archiveSettings.view==='타임라인'?'timeline':'')}>{experiences.filter(e=>(archiveSettings.type==='전체'||e.type===archiveSettings.type)&&(archiveSettings.status==='전체'||(archiveSettings.status==='회고 있음'?e.reflections.length>0:archiveSettings.status==='회고 전'?e.reflections.length===0:!!drafts[e.id]?.dirty))&&(e.title+' '+e.action+' '+e.role).includes(archiveSettings.search)).map((e,i)=><article className="archive-card" key={e.id}><button className="archive-open" onClick={()=>openArchive(e.id)} aria-label={e.title+' 경험 기록 열기'}><Thumb tone={i}/><div><small>{e.type} · {e.period}</small><h3>{e.title}</h3><p>{e.action||'직접 한 행동 미확인'}</p><div className="tag-row"><span>회고 {e.reflections.length}개</span>{drafts[e.id]?.dirty&&<span className="draft-badge">미저장 초안 · 이어쓰기</span>}</div>{e.reflections.at(-1)&&<blockquote>{e.reflections.at(-1)!.body}</blockquote>}</div></button><div className="card-actions"><button onClick={()=>openArchive(e.id,'회고')}>{drafts[e.id]?.dirty?'회고 이어쓰기':e.reflections.length?'회고 더 남기기':'회고 남기기'}</button><button onClick={()=>highlight({type:'node',key:e.id,label:e.title+'의 경험 근거',ids:[e.id]},true)}>연결 보기</button></div></article>)}</div>{experiences.filter(e=>(archiveSettings.type==='전체'||e.type===archiveSettings.type)&&(archiveSettings.status==='전체'||(archiveSettings.status==='회고 있음'?e.reflections.length>0:archiveSettings.status==='회고 전'?e.reflections.length===0:!!drafts[e.id]?.dirty))&&(e.title+' '+e.action+' '+e.role).includes(archiveSettings.search)).length===0&&<Empty title="현재 조건에 맞는 경험이 없어요" text="필터를 바꾸거나 새로운 경험을 남겨보세요." label="필터 초기화" action={()=>setArchiveSettings(s=>({...s,search:'',type:'전체',status:'전체'}))}/>}</>:<><button className="text-button back-button" onClick={()=>setArchiveId(null)}><Icon name="back"/>경험 목록으로</button><section className="experience-heading"><div><small>{current.type} · {current.period}</small><h2>{current.title}</h2><span className="pill">회고 {current.reflections.length}개</span>{drafts[current.id]?.dirty&&<span className="pill">미저장 초안 보관 중</span>}</div><div className="inline-actions"><button onClick={()=>setEditor(current)}>경험 편집</button><button className="danger-text" onClick={()=>setDeleteId(current.id)}>경험 삭제</button></div></section><div className="tabs" role="tablist" aria-label="경험 상세 보기">{['경험 기록','회고','연결 근거'].map(t=><button role="tab" aria-selected={archiveTab===t} className={archiveTab===t?'active':''} key={t} onClick={()=>setArchiveTab(t)}>{t}{t==='회고'?' '+current.reflections.length:''}</button>)}</div><section role="tabpanel" aria-label={archiveTab}>{archiveTab==='경험 기록'&&<div className="experience-details"><div className="panel"><h3>직접 한 일</h3><dl className="detail-list"><div><dt>개인 역할</dt><dd>{current.role||'미확인'}</dd></div><div><dt>직접 한 행동</dt><dd>{current.action||'미확인'}</dd></div><div><dt>결과·피드백</dt><dd>{current.result||'미확인'}</dd></div></dl><h3>원문 근거</h3><blockquote>{current.quote||'원문 근거 미확인'}</blockquote><small>회고를 저장해도 이 원문은 자동으로 바뀌지 않습니다.</small></div><div className="panel"><h3>남긴 결과물</h3>{current.artifacts.length?current.artifacts.map(a=><div className="artifact-item" key={a}><Icon name="archive"/>{a}<small>제목 기록 · 파일 미연결</small></div>):<p className="muted">결과물 제목은 아직 미확인입니다.</p>}<h3>6축 연결 근거</h3><div className="tag-row">{current.axes.length?current.axes.map(a=><button key={a} onClick={()=>focusAxis(a)}>{axisLabel(a)}<Icon name="arrow" size={13}/></button>):<span>미확인</span>}</div><button className="primary full" onClick={()=>setArchiveTab('회고')}><Icon name="chat"/>{drafts[current.id]?.dirty?'회고 이어쓰기':'이 경험에 회고 남기기'}</button></div></div>}{archiveTab==='회고'&&<ReflectionPanel key={current.id} experience={current} draft={drafts[current.id]||startDraft(current)} update={p=>updateDraft(current.id,p)} save={d=>saveReflection(current,d)} returnToRecord={()=>setArchiveTab('경험 기록')} graph={()=>{setExpanded(true);highlight({type:'node',key:current.id,label:current.title+' · 저장한 회고',ids:[current.id]},true);}} explore={()=>navigate('explore')}/>}{archiveTab==='연결 근거'&&<section className="panel"><h3>이 경험에서 이어진 연결</h3>{aliveLinks.filter(l=>l.from===current.id||l.to===current.id).map(l=><article className="connection-row" key={l.id}><div><span className="state">{l.status==='confirmed'?'확인됨':'연결 제안'}</span><h3>{l.label}</h3><p>{l.reason}</p><small>{experiences.find(e=>e.id===l.from)?.title} ↔ {experiences.find(e=>e.id===l.to)?.title}</small></div><button onClick={()=>focusLink(l)}>지도에서 연결 보기</button><button onClick={()=>setLinkEditor(l)}>확인·수정</button></article>)}{aliveLinks.filter(l=>l.from===current.id||l.to===current.id).length===0&&<p className="muted">다른 활동과의 연결은 아직 미확인입니다. 새 기록이 자동으로 강점이나 관계로 확정되지는 않습니다.</p>}<button className="primary" onClick={()=>highlight({type:'node',key:current.id,label:current.title+'의 근거',ids:[current.id]},true)}>내 성장에서 근거 보기</button></section>}</section></>}</>}
 {route==='explore'&&<><PageTitle eyebrow="NEXT EXPERIENCE" title="발견한 것을 다음 경험으로" subtitle="성장 활동과 채용·직무 요건을 나누어 살펴보고, 내 활동 근거를 직접 연결해요."/><div className="tabs" role="tablist" aria-label="탐색 대상"><button role="tab" aria-selected={exploreMode==='activities'} className={exploreMode==='activities'?'active':''} onClick={()=>setExploreMode('activities')}>성장 활동</button><button role="tab" aria-selected={exploreMode==='jobs'} className={exploreMode==='jobs'?'active':''} onClick={()=>setExploreMode('jobs')}>채용·직무</button></div>{exploreMode==='activities'?<section role="tabpanel" aria-label="성장 활동"><div className="explore-tools"><label className="field">관심 경험 렌즈<select value={exploreSettings.axis} onChange={e=>setExploreSettings(s=>({...s,axis:e.target.value}))}><option value="전체">전체</option>{axes.map(a=><option key={a.id} value={a.id}>{a.label}</option>)}</select></label><label className="field">출처<select value={exploreSettings.source} onChange={e=>setExploreSettings(s=>({...s,source:e.target.value}))}>{['전체','학교 공지','학과 공지','Challenge Square','외부 활동'].map(s=><option key={s}>{s}</option>)}</select></label><button aria-pressed={exploreSettings.saved} className={exploreSettings.saved?'selected':''} onClick={()=>setExploreSettings(s=>({...s,saved:!s.saved}))}><Icon name="bookmark"/>저장한 활동만 {bookmarks.length}</button></div><div className="activity-grid">{filteredActivities.map((a,i)=><ActivityCard key={a.id} activity={a} saved={bookmarks.includes(a.id)} toggle={()=>toggleBookmark(a.id)} open={()=>setActivity(a)} tone={i}/>)}</div>{filteredActivities.length===0&&<Empty title="이 조건의 예시 활동이 없어요" text="실제 공고와 추천 엔진은 아직 연결하지 않았습니다." label="필터 초기화" action={()=>setExploreSettings({source:'전체',axis:'전체',saved:false})}/>}</section>:<section role="tabpanel" aria-label="채용·직무"><JobExplorer experiences={experiences} recheckIds={recheckIds} overrides={careerOverrides} field={careerField} onFieldChange={setCareerField} savedIDs={jobBookmarks} onToggleSave={id=>setJobBookmarks(old=>old.includes(id)?old.filter(x=>x!==id):[...old,id])} onOverrideChange={(reqId,value)=>{setCareerOverrides(old=>({...old,[reqId]:value}));change('채용 요건 연결 확인·수정');setToast('요건과 경험의 연결을 반영했어요. 지원 자격 충족이나 실제 AI 분석을 뜻하지 않습니다.');}} onHighlight={careerHighlight} onOpenArchive={id=>openArchive(id)}/></section>}</>}
 {route==='data'&&<><PageTitle eyebrow="DATA & SETTINGS" title="내 데이터와 분석 상태" subtitle="저장과 분석을 나누고, 개인 기록은 공유 공고·채용 요건과 분리합니다."/><div className="settings-grid"><section className="panel"><div className="panel-head"><h2>개인 분석 대기열</h2><span className={'state '+(stale?'waiting':'')}>{analysis}</span></div><p>{queueLabel}</p><div className="cache-comparison"><div><small>마지막 완료 분석</small><b>{doneRevision===0?'초기 예시 분석':'완료 상태 예시 · 변경 '+doneRevision}</b></div><div><small>새 기록 변경</small><b>{revision}건의 데모 변경{stale?' · 기존 분석 재검토 필요':''}</b></div></div><div className="inline-actions"><button disabled={analysis!=='대기'} onClick={()=>setAnalysis('진행 중')}>분석 시작 시뮬레이션</button><button className="primary" disabled={analysis!=='진행 중'} onClick={()=>{setDoneRevision(revision);setAnalysis('완료');setQueueLabel('새 변경 없음');}}>분석 완료 시뮬레이션</button></div><small>상태만 변경합니다. 실제 분석·모델·비용 측정은 수행하지 않습니다.</small></section><section className="panel"><h2>내가 관리하는 기록</h2><div className="data-counts"><span><b>{experiences.length}</b>경험</span><span><b>{experiences.reduce((n,e)=>n+e.reflections.length,0)}</b>저장한 회고</span><span><b>{Object.values(drafts).filter(d=>d.dirty).length}</b>미저장 초안</span></div><p className="muted">목적별 동의·열람·정정·삭제·철회를 적용하는 설계입니다. 실제 동의/영구 삭제 API는 연결하지 않았습니다.</p><button className="danger-text" onClick={()=>setResetOpen(true)}>데모 데이터 초기화</button></section></div><div className="settings-grid"><details className="panel"><summary>공통 모집글 ETL <span>공유 가능한 공고만</span></summary><FlowLane items={['허용된 전체 공고 수집','원문·출처·접근 범위 보관','정규화·중복 제거','대형 모델 비동기 분석','조건·마감·원문 검증','공통 DB·임베딩·캐시 저장','신규·내용/분석 버전 변경만 갱신']}/><small>교내 제한 공고는 같은 접근 권한 범위에서만 재사용합니다.</small></details><details className="panel"><summary>학생별 비공개 분석 <span>개인 기록은 격리</span></summary><FlowLane items={['확인된 경험·회고 저장','목적별 동의·사용자별 격리','변경을 묶어 개인 분석 큐','대형 모델로 패턴·관계 후보 분석','근거·불확실성·버전 보관','개인 캐시와 추천에서 재사용','정정·삭제를 파생 데이터에 전파']}/><small>개인 원문·프로필·임베딩·추천 이력은 공통 인덱스에 섞지 않습니다.</small></details></div><CareerDataPanel/><details className="panel"><summary>모델·추천 방식의 검증 경계</summary><p>실시간 경량 모델은 회고 사실 정리, 비동기 대형 모델은 깊은 분석·공고 정제에 사용하는 설계입니다. 현재 모델·GPU/API 환경·평가셋·예산은 미확정입니다.</p><div className="method-grid">{['규칙·태그·BM25','임베딩 유사도','하이브리드 검색','경량 LLM 재정렬'].map(x=><div key={x}><b>{x}</b><small>미선정 · 비교 예정 · 미실측</small></div>)}</div><p>추천 품질, 조건 위반, 설명의 사실성, p95 지연과 요청당 비용을 분리해 평가합니다. 비동기 자체가 저비용을 보장하지 않습니다.</p></details></>}
 </main></div>
 {activity&&<Modal title={activity.title} close={()=>setActivity(null)}><span className="pill">가상 공고 · 추천 방식 미선정</span><Thumb tone={2}/><dl className="detail-list"><div><dt>실제 과업 예시</dt><dd>{activity.task}</dd></div><div><dt>남길 결과물</dt><dd>{activity.output}</dd></div><div><dt>지원·실행 조건</dt><dd>{activity.condition}</dd></div><div><dt>출처·일정</dt><dd>{activity.source} · {activity.date}<br/>예시 확인일 2026.10.07 · 실제 마감 검증 미연결</dd></div><div><dt>원문 URL</dt><dd>가상 공고이므로 실제 원문 URL이 없습니다.</dd></div></dl><h3>왜 내 경험과 연결될까요?</h3><BridgeGraph records={experiences.filter(e=>activity.ids.includes(e.id))} axis={axisLabel(activity.axis)} title={activity.title}/><p className="muted">기존 경험을 다른 맥락에서 시험해볼 수 있다는 제안입니다. 실제 참여·합격·성과를 보장하지 않습니다.</p><div className="modal-actions"><button onClick={()=>toggleBookmark(activity.id)}>{bookmarks.includes(activity.id)?'관심 활동 저장 취소':'관심 활동 저장'}</button><button className="primary" onClick={()=>activityFocus(activity)}>내 경험과 연결 보기</button></div></Modal>}
 {editor&&<ExperienceEditor experience={editor} close={()=>setEditor(null)} save={saveExperience}/>}
 {deleteId&&<Modal title="경험과 관련 기록을 삭제할까요?" close={()=>setDeleteId(null)}><p><b>{experiences.find(e=>e.id===deleteId)?.title}</b>의 원문·결과물 제목·저장한 회고·미저장 초안과 관련 지도 연결을 함께 제거합니다.</p><p>6축 근거 수와 분석의 관련 경험도 줄어들고, 기존 해석은 재검토 대기로 표시됩니다. 이 작업은 데모 메모리에서만 실행합니다.</p><div className="modal-actions"><button onClick={()=>setDeleteId(null)}>취소</button><button className="danger" onClick={deleteExperience}>경험과 관련 기록 삭제</button></div></Modal>}
 {linkEditor&&<LinkEditor link={linkEditor} close={()=>setLinkEditor(null)} save={l=>{setLinks(old=>old.map(x=>x.id===l.id?l:x));setLinkEditor(null);change('연결 확인·수정');setToast('학생이 확인한 연결 설명을 반영했어요.');}} remove={()=>{setLinks(old=>old.filter(l=>l.id!==linkEditor.id));setLinkEditor(null);setSelectedLink(null);change('연결 제거');}}/>}
 {patternEdit&&<PatternEditor label={overrides[patternEdit]?.label||patterns.find(p=>p.id===patternEdit)!.title} note={overrides[patternEdit]?.note||''} close={()=>setPatternEdit(null)} save={(label,note)=>{setOverrides(o=>({...o,[patternEdit]:{label,note,status:'학생이 수정한 가설'}}));setFocus(old=>old?.key===patternEdit?{...old,label}:old);change('분석 가설 수정');setPatternEdit(null);}}/>}
 {resetOpen&&<Modal title="데모를 처음 상태로 되돌릴까요?" close={()=>setResetOpen(false)}><p>추가·수정한 경험, 저장한 회고, 미저장 초안, 연결 확인, 관심 활동이 모두 초기화됩니다. 실제 서버 데이터는 처리하지 않습니다.</p><div className="modal-actions"><button onClick={()=>setResetOpen(false)}>계속 사용</button><button className="danger" onClick={reset}>데모 초기화 확인</button></div></Modal>}
 {info&&<Modal title="데모와 시각화 안내" close={()=>setInfo(false)}><p>v0.6은 6개의 가상 경험, 성장 활동 예시, 공식 채용 공고 3건의 수동 조사 표본을 React 메모리로 연결한 프로토타입입니다. 실제 AI·학교 계정·외부 API·크롤러·DB·영구 저장은 연결하지 않았습니다.</p><p>분석은 근거를 열어볼 수 있는 예시 가설입니다. 6축 도형은 연결된 경험 수의 분포이며 능력 점수·순위·성격·직업 판정이 아닙니다.</p><p>회고는 경험의 아카이브 안에 버전별 저장되며 원문과 별도로 유지됩니다. 미저장 초안은 화면을 이동해도 메모리에 남지만 새로고침 시 사라집니다.</p><p>실선은 기록/학생 확인, 점선은 확인 전 연결입니다. 실제 학생 기록 검증이나 실제 참여의 증거가 아닙니다.</p><button className="primary full" onClick={()=>setInfo(false)}>확인</button></Modal>}
 </div>;
}

function ExperienceGraph({experiences,links,focusIds,tick,expanded,selectNode,selectLink}:{experiences:Experience[];links:Link[];focusIds:string[]|null;tick:number;expanded:boolean;selectNode:(n:Node)=>void;selectLink:(l:Link)=>void}){
 const nodes=useMemo<Node[]>(()=>experiences.flatMap((e,i)=>{const x=[160,500,840][i%3],y=125+Math.floor(i/3)*285;const arr:Node[]=[{id:e.id,eid:e.id,label:e.title,kind:'experience',x,y}];if(expanded){e.artifacts.slice(0,1).forEach((a,j)=>arr.push({id:'artifact-'+e.id+'-'+j,eid:e.id,label:a,kind:'artifact',x:x-45,y:y+88}));e.reflections.slice(-2).forEach((r,j)=>arr.push({id:r.id,eid:e.id,label:'회고 v'+r.version,kind:'reflection',x:x+55,y:y+88+j*47}));}return arr;}),[experiences,expanded]);
 const lookup=Object.fromEntries(nodes.filter(n=>n.kind==='experience').map(n=>[n.eid,n]));const selected=new Set(focusIds||[]);const height=Math.max(625,...nodes.map(n=>n.y+72));const dim=(id:string)=>focusIds!==null&&!selected.has(id);return <div className="graph-scroll"><svg className="experience-graph" viewBox={'0 0 1000 '+height} role="group" aria-label="활동 사이의 재사용·후속 경험 그래프"><defs><filter id="soft-glow" x="-40%" y="-80%" width="180%" height="260%"><feGaussianBlur stdDeviation="6"/></filter></defs>{links.map((l,i)=>{const a=lookup[l.from],b=lookup[l.to];if(!a||!b)return null;const horizontal=Math.abs(a.y-b.y)<10;const mx=(a.x+b.x)/2,my=(a.y+b.y)/2;const offset=horizontal?-54:((i%2?1:-1)*48);const d=horizontal?`M${a.x} ${a.y-38} Q${mx} ${my-110} ${b.x} ${b.y-38}`:`M${a.x} ${a.y+36} Q${mx+offset} ${my} ${b.x} ${b.y-36}`;const active=focusIds!==null&&selected.has(a.eid)&&selected.has(b.eid);return <g key={l.id} className={'graph-edge '+l.status+(active?' lit':'')+(focusIds!==null&&!active?' dim':'')} role="button" tabIndex={0} aria-label={'연결 근거: '+l.label} onClick={()=>selectLink(l)} onKeyDown={e=>activate(e,()=>selectLink(l))}><title>{l.reason}</title><path className="edge-hit" d={d}/><path className="edge-path" d={d}/>{active&&<path className="edge-flow" d={d}/>}<rect x={mx-73} y={(horizontal?my-64:my)-13} width="146" height="26" rx="13"/><text x={mx} y={(horizontal?my-64:my)+4} textAnchor="middle">{l.label}</text></g>})}{expanded&&nodes.filter(n=>n.kind!=='experience').map(n=>{const a=lookup[n.eid];return <line key={'stem'+n.id} x1={a.x} y1={a.y+33} x2={n.x} y2={n.y-18} className={'evidence-stem '+(dim(n.eid)?'dim':'')}/>})}{nodes.map(n=><g key={n.id} className={'graph-node '+n.kind+(dim(n.eid)?' dim':'')+(focusIds!==null&&selected.has(n.eid)?' lit':'')} role="button" tabIndex={0} aria-label={'근거 선택: '+n.label} aria-pressed={focusIds!==null&&selected.has(n.eid)} onClick={()=>selectNode(n)} onKeyDown={e=>activate(e,()=>selectNode(n))}><title>{n.label}</title>{n.kind==='experience'?<>{focusIds!==null&&selected.has(n.eid)&&<rect key={'pulse'+tick} className="node-halo" x={n.x-88} y={n.y-45} width="176" height="90" rx="23"/>}<rect className="node-body" x={n.x-79} y={n.y-34} width="158" height="68" rx="17"/><text className="node-kind" x={n.x} y={n.y-9} textAnchor="middle">{experiences.find(e=>e.id===n.eid)?.type}</text><text className="node-title" x={n.x} y={n.y+14} textAnchor="middle">{n.label.length>13?n.label.slice(0,12)+'…':n.label}</text><text className="node-period" x={n.x} y={n.y+53} textAnchor="middle">{experiences.find(e=>e.id===n.eid)?.period}</text></>:<><rect className="node-body" x={n.x-62} y={n.y-18} width="124" height="36" rx={n.kind==='reflection'?18:8}/><text x={n.x} y={n.y+4} textAnchor="middle">{n.kind==='artifact'?'▣ ':'◯ '}{n.label.length>11?n.label.slice(0,10)+'…':n.label}</text></>}</g>)}</svg></div>}
function HexLens({counts,total,active,select}:{counts:{axis:typeof axes[number];count:number}[];total:number;active:string;select:(a:Axis)=>void}){const point=(i:number,r:number)=>[195+Math.sin(i*Math.PI/3)*r,178-Math.cos(i*Math.PI/3)*r];const pts=(r:number)=>axes.map((_,i)=>point(i,r).join(',')).join(' ');const values=counts.map((c,i)=>point(i,total?120*c.count/total:0).join(',')).join(' ');return <div className="hex-wrap"><svg viewBox="0 0 390 358" role="group" aria-label="6축 경험 근거 분포: 반경은 연결 경험 수를 전체 경험 수로 나눈 비율">{[.25,.5,.75,1].map(r=><polygon key={r} points={pts(120*r)} className="hex-grid"/>)}{axes.map((a,i)=>{const p=point(i,120);return <line key={a.id} x1="195" y1="178" x2={p[0]} y2={p[1]} className="hex-spoke"/>})}<polygon points={values} className="hex-value"/>{counts.map(({axis,count},i)=>{const p=point(i,120*(total?count/total:0)),label=point(i,151);return <g key={axis.id} className={'hex-axis '+(active===axis.id?'active':'')} role="button" tabIndex={0} aria-label={axis.label+' '+(count?'근거 '+count+'개':'미확인')+' 강조'} aria-pressed={active===axis.id} onClick={()=>select(axis.id)} onKeyDown={e=>activate(e,()=>select(axis.id))}><circle cx={p[0]} cy={p[1]} r="6"/><rect x={label[0]-42} y={label[1]-14} width="84" height="42" rx="8"/><text x={label[0]} y={label[1]+1} textAnchor="middle">{axis.label}</text><text className="hex-count" x={label[0]} y={label[1]+18} textAnchor="middle">{count?'근거 '+count+'개':'미확인'}</text></g>})}</svg><small>전체 {total}개 경험 기준 · 연결 근거의 분포</small></div>}
function ArchiveFilters({settings,update}:{settings:{search:string;type:string;status:string;view:string};update:(p:Partial<typeof settings>)=>void}){return <div className="archive-tools"><label className="search-field"><Icon name="search"/><input aria-label="경험 검색" placeholder="경험·역할·행동 검색" value={settings.search} onChange={e=>update({search:e.target.value})}/></label><select aria-label="경험 유형 필터" value={settings.type} onChange={e=>update({type:e.target.value})}>{['전체','교과','프로젝트','비교과'].map(x=><option key={x}>{x}</option>)}</select><select aria-label="회고 상태 필터" value={settings.status} onChange={e=>update({status:e.target.value})}>{['전체','회고 있음','회고 전','이어쓰기'].map(x=><option key={x}>{x}</option>)}</select><div className="segmented">{['갤러리','타임라인'].map(v=><button key={v} className={settings.view===v?'selected':''} aria-pressed={settings.view===v} onClick={()=>update({view:v})}>{v}</button>)}</div></div>}
function ReflectionPanel({experience:e,draft:d,update,save,returnToRecord,graph,explore}:{experience:Experience;draft:Draft;update:(p:Partial<Draft>)=>void;save:(d:Draft)=>void;returnToRecord:()=>void;graph:()=>void;explore:()=>void}){const next=()=>d.step<2?update({step:d.step+1}):update({body:[d.role&&'역할: '+d.role,d.action&&'행동: '+d.action,d.result&&'결과: '+d.result,d.learn&&'배운 점: '+d.learn].filter(Boolean).join('\n'),ready:true});const valid=d.step===0?d.role.trim():d.step===1?d.action.trim():d.learn.trim();const [newForm,setNewForm]=useState(e.reflections.length===0||d.dirty);useEffect(()=>{if(d.dirty)setNewForm(true);},[d.dirty]);return <><div className="reflection-heading"><div><h3>이 경험에 남긴 회고 {e.reflections.length}개</h3><small>원문 근거와 별도 버전으로 보관합니다.</small></div><button className="primary" onClick={()=>setNewForm(true)}>{d.dirty?'미저장 회고 이어쓰기':'새 회고 남기기'}</button></div>{newForm&&<div className="reflection-workspace"><section className="panel helper"><div className="stepper">{['역할','행동·결과','배운 점'].map((v,i)=><button disabled={i>d.step} aria-current={i===d.step?'step':undefined} className={i===d.step?'current':''} key={v} onClick={()=>update({step:i})}><b>{i+1}</b>{v}</button>)}</div><p className="bubble">{['어떤 역할을 직접 맡았나요? 팀 전체 성과와 나의 행동을 나누어 봐요.','직접 한 행동과 결과를 따로 확인해요. 결과가 없거나 모르면 비워둘 수 있어요.','무엇을 배웠고 다음에는 무엇을 바꾸고 싶나요?'][d.step]}</p>{d.step===0&&<label className="field">내가 맡은 역할<textarea value={d.role} onChange={ev=>update({role:ev.target.value,ready:false})}/></label>}{d.step===1&&<><label className="field">직접 한 행동<textarea value={d.action} onChange={ev=>update({action:ev.target.value,ready:false})}/></label><label className="field">결과 또는 피드백<textarea value={d.result} onChange={ev=>update({result:ev.target.value,ready:false})} placeholder="모르면 비워둘 수 있어요"/></label></>}{d.step===2&&<label className="field">배운 점과 다음 시도<textarea value={d.learn} onChange={ev=>update({learn:ev.target.value,ready:false})}/></label>}<button className="primary" disabled={!valid||(d.step===2&&d.ready)} onClick={next}>{d.step===2?'입력 사실로 회고 초안 만들기':'다음 질문'}</button><small>실제 AI 응답이 아닌 사실 조합 데모. 초안은 화면을 옮겨도 메모리에 남습니다.</small></section><section className="panel"><h3>내가 확인하는 회고 초안</h3><textarea aria-label="편집 가능한 회고 초안" className="draft-editor" disabled={!d.ready} value={d.body} onChange={ev=>update({body:ev.target.value})} placeholder="세 단계 질문을 확인한 뒤 초안을 직접 수정해요."/><p className="muted">원래 근거 문장은 바꾸지 않고, 이 경험에 회고 v{e.reflections.length+1}로 저장합니다.</p><button className="primary full" disabled={!d.ready||!d.body.trim()} onClick={()=>{save(d);setNewForm(false);}}>확인하고 이 경험에 회고 저장</button>{d.dirty&&<span className="draft-badge">미저장 초안 · 이어쓰기 가능</span>}</section></div>}{e.reflections.length>0&&<section className="reflection-history">{[...e.reflections].reverse().map(r=><article className="panel" key={r.id}><div className="panel-head"><h3>회고 v{r.version}</h3><small>{r.at}</small></div><p className="saved-body">{r.body}</p><details><summary>함께 보관한 구조화 사실</summary><dl className="detail-list"><div><dt>역할</dt><dd>{r.facts.role}</dd></div><div><dt>행동</dt><dd>{r.facts.action}</dd></div><div><dt>결과</dt><dd>{r.facts.result||'미확인'}</dd></div><div><dt>배운 점</dt><dd>{r.facts.learn}</dd></div></dl></details></article>)}</section>}<div className="reflection-next"><button onClick={returnToRecord}>경험 기록으로 돌아가기</button><button disabled={e.reflections.length===0} onClick={graph}>저장한 회고의 연결 보기</button><button className="primary" onClick={explore}>다음 활동 탐색</button></div></>}
function ActivityCard({activity:a,saved,toggle,open,tone}:{activity:Activity;saved:boolean;toggle:()=>void;open:()=>void;tone:number}){return <article className="activity-card"><button className="activity-open" onClick={open} aria-label={a.title+' 상세 보기'}><Thumb tone={tone}/><div><small>{a.source} · {a.kind}</small><h3>{a.title}</h3><p>{axisLabel(a.axis)} 경험을 다른 맥락에서 써보는 예시</p><span className="pill">가상 공고 · 조건 미검증</span></div></button><button className={'bookmark '+(saved?'saved':'')} aria-label={(saved?'저장 취소: ':'관심 활동 저장: ')+a.title} aria-pressed={saved} onClick={toggle}><Icon name="bookmark"/></button></article>}
function BridgeGraph({records,axis,title}:{records:Experience[];axis:string;title:string}){if(!records.length)return <p className="muted">현재 연결 가능한 과거 경험은 미확인입니다. 없는 경험을 새로 생성해 추천 근거로 쓰지 않습니다.</p>;return <div className="bridge-graph" aria-label="과거 경험에서 다음 활동으로 이어지는 제안"><div>{records.map(e=><span key={e.id}>{e.title}</span>)}</div><div className="bridge-arrow"><span>근거 연결</span><Icon name="arrow"/></div><span className="bridge-axis">{axis}<small>탐색할 가설</small></span><div className="bridge-arrow proposed"><span>새 시도 제안</span><Icon name="arrow"/></div><span className="bridge-opportunity">{title}<small>미참여 · 성과 보장 아님</small></span></div>}
function ExperienceEditor({experience,close,save}:{experience:Experience;close:()=>void;save:(e:Experience)=>void}){const [e,setE]=useState(experience);const set=(k:keyof Experience,value:unknown)=>setE(old=>({...old,[k]:value}));return <Modal title={e.id?'경험 기록 편집':'새 경험 남기기'} close={close}><div className="editor-grid"><label className="field">경험 제목<input value={e.title} onChange={ev=>set('title',ev.target.value)} placeholder="내가 참여한 경험"/></label><label className="field">유형<select value={e.type} onChange={ev=>set('type',ev.target.value)}>{['교과','프로젝트','비교과'].map(x=><option key={x}>{x}</option>)}</select></label><label className="field">기간<input value={e.period} onChange={ev=>set('period',ev.target.value)}/></label><label className="field">내 역할<input value={e.role} onChange={ev=>set('role',ev.target.value)}/></label><label className="field wide">직접 한 행동<textarea value={e.action} onChange={ev=>set('action',ev.target.value)}/></label><label className="field wide">결과·피드백<textarea value={e.result} onChange={ev=>set('result',ev.target.value)}/></label><label className="field wide">원문 근거 문장<textarea value={e.quote} onChange={ev=>set('quote',ev.target.value)} placeholder="직접 쓴 문장이나 확인할 발췌"/></label><label className="field wide">결과물 제목<input value={e.artifacts.join(', ')} onChange={ev=>set('artifacts',ev.target.value.split(',').map(x=>x.trim()).filter(Boolean))} placeholder="쉼표로 구분 · 실제 파일 업로드 미연결"/></label></div><fieldset className="axis-choices"><legend>어떤 경험 렌즈에 직접 연결할까요?</legend>{axes.map(a=><label key={a.id}><input type="checkbox" checked={e.axes.includes(a.id)} onChange={()=>set('axes',e.axes.includes(a.id)?e.axes.filter(x=>x!==a.id):[...e.axes,a.id])}/>{a.label}</label>)}</fieldset><small>축 연결은 자기 확인한 기록 분류이며 능력 평가가 아닙니다. 모르는 사실은 비워둘 수 있어요.</small><button className="primary full" disabled={!e.title.trim()} onClick={()=>save(e)}>확인하고 경험 기록 저장</button></Modal>}
function LinkEditor({link,close,save,remove}:{link:Link;close:()=>void;save:(l:Link)=>void;remove:()=>void}){const [label,setLabel]=useState(link.label),[reason,setReason]=useState(link.reason);return <Modal title={link.status==='proposed'?'연결 제안을 확인해요':'확인된 연결 수정'} close={close}><span className="pill">학생이 수정·제거할 수 있는 관계</span><label className="field">연결 설명<input value={label} onChange={e=>setLabel(e.target.value)}/></label><label className="field">근거 또는 다른 해석<textarea value={reason} onChange={e=>setReason(e.target.value)}/></label><p className="muted">같은 관심으로 맡았는지, 팀의 필요로 맡았는지도 구분해 주세요. 제안 자체는 능력의 증거가 아닙니다.</p><div className="modal-actions"><button onClick={remove}>이 연결 제거</button><button className="primary" disabled={!label.trim()} onClick={()=>save({...link,label:label.trim(),reason,status:'confirmed'})}>확인하고 연결 반영</button></div></Modal>}
function PatternEditor({label,note,close,save}:{label:string;note:string;close:()=>void;save:(l:string,n:string)=>void}){const [l,setL]=useState(label),[n,setN]=useState(note);return <Modal title="분석 가설을 내 말로 수정" close={close}><label className="field">내가 확인한 해석<input value={l} onChange={e=>setL(e.target.value)}/></label><label className="field">근거·다른 맥락<textarea value={n} onChange={e=>setN(e.target.value)}/></label><button className="primary full" disabled={!l.trim()} onClick={()=>save(l.trim(),n)}>수정한 가설 반영</button></Modal>}
function FlowLane({items}:{items:string[]}){return <ol className="flow-lane">{items.map(i=><li key={i}>{i}</li>)}</ol>}
function PageTitle({eyebrow,title,subtitle,action}:{eyebrow:string;title:string;subtitle:string;action?:ReactNode}){return <div className="page-title"><div><small>{eyebrow}</small><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>}
function Empty({title,text,label,action}:{title:string;text:string;label:string;action:()=>void}){return <div className="empty"><Icon name="graph" size={36}/><h3>{title}</h3><p>{text}</p><button onClick={action}>{label}</button></div>}
function Modal({title,close,children}:{title:string;close:()=>void;children:ReactNode}){const ref=useRef<HTMLElement>(null),closeRef=useRef(close);closeRef.current=close;useEffect(()=>{const previous=document.activeElement as HTMLElement|null;const oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.querySelector<HTMLElement>('button,input,textarea,select')?.focus();const handler=(e:globalThis.KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();closeRef.current();}if(e.key==='Tab'){const all=Array.from(ref.current?.querySelectorAll<HTMLElement>('button,input,textarea,select,a,[tabindex="0"]')||[]).filter(el=>!el.hasAttribute('disabled')&&el.getClientRects().length>0);const first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',handler);return()=>{document.removeEventListener('keydown',handler);document.body.style.overflow=oldOverflow;if(previous?.isConnected)previous.focus();};},[]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close();}}><section className="modal" role="dialog" aria-modal="true" aria-label={title} ref={ref}><div className="modal-head"><h2>{title}</h2><button aria-label="닫기" onClick={close}><Icon name="close"/></button></div>{children}</section></div>}
